import {workItems,equipmentReceipt,flowSteps,flowStep,flowSections,planningUpdate,recordGaps,purchaseNeeds,closeoutLabel} from './workflow-model.js';
'use strict';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),usd=x=>x===null||x===undefined?'Unconfirmed':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(x/100),date=x=>x?new Date(x).toLocaleString():'Unscheduled';
let data,events=[],selected=new URLSearchParams(location.search).get('event'),tab='events',prep=null,dirtyForm=null,showAllDetails=false,viewStep=null,viewSection=0,lastCommandOk=null;
async function api(path,opts={}){const r=await fetch(path,{...opts,headers:{'Content-Type':'application/json'}});const d=await r.json();if(r.status===401){location.replace('/admin/login.html?next='+encodeURIComponent(location.pathname+location.search));throw Error('Sign in required.');}if(!r.ok)throw Error(d.error||'Request failed.');return d;}
const state=()=>data.state,ev=()=>state().events[selected]||structuredClone(data.eventTemplate),eventDoc=()=>events.find(x=>x.id===selected),field=(label,name,value='',type='text',extra='')=>`<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`,dollarInput=(name,cents)=>`<input aria-label="${esc(name)}" name="${esc(name)}" type="number" min="0" step="0.01" value="${cents===null?'':cents/100}" placeholder="Unknown">`,check=(label,name,value)=>`<label class="checkline"><input name="${name}" type="checkbox" ${value?'checked':''}>${esc(label)}</label>`;
const cents=x=>x===''?null:Math.round(Number(x)*100),nullable=x=>x===''?null:Number(x),localTime=x=>{if(!x)return '';const d=new Date(x);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);},iso=x=>x?new Date(x).toISOString():'';
function notify(m){$('#message').textContent=m;}
function clean(){if(dirtyForm){notify('Save the form you are editing before switching or making another change.');return false;}return true;}
let commandPending=false;
async function command(action,payload,form=null){lastCommandOk=null;if(commandPending)return;if(dirtyForm&&dirtyForm!==form){notify('Save the current form first.');return;}const controls=form?[...form.querySelectorAll('button')]:[];commandPending=true;for(const b of controls)b.disabled=true;const scrollY=window.scrollY;try{data=await api('/api/admin/operations',{method:'POST',body:JSON.stringify({version:state().version,action,payload})});dirtyForm=null;if(prep)prep.operationsVersion=state().version;if(action==='advance'||action==='reopen'){viewStep=null;viewSection=0;}render();window.scrollTo(0,scrollY);notify('Saved. Shared operations updated.');lastCommandOk=true;}catch(e){for(const b of controls)b.disabled=false;notify(e.message);lastCommandOk=false;}finally{commandPending=false;}}
async function load(){if(!clean())return;try{data=await api('/api/admin/operations');events=[];let offset=0;do{const r=await api('/api/admin/inquiries?offset='+offset);events.push(...r.items);offset=r.nextOffset;}while(offset!==null);if(selected&&!events.some(e=>e.id===selected))selected=null;if(selected)prep=await api('/api/admin/inquiries/'+selected+'/preparation');render();notify('');}catch(e){notify(e.message);}}
function eventName(id){const d=events.find(x=>x.id===id);return d?.payload.details.company||d?.payload.details.name||id;}
function metric(title,value,note){return `<div class="ops-card"><span class="kicker">${title}</span><strong class="metric">${value}</strong><small>${note}</small></div>`;}
function render(){document.querySelector('.ops').classList.toggle('event-mode',tab==='events'&&!!selected);$('#discard').hidden=!dirtyForm;document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.tab===tab));$('#content').innerHTML=tab==='inventory'?inventoryView():tab==='staff'?staffView():tab==='activity'?activityView():selected?eventView():overview();if(tab==='events'&&selected)focusStage();if(tab==='events'&&selected&&ev().stage===8)document.querySelectorAll('#content form input,#content form select,#content form textarea,#content form button').forEach(x=>x.disabled=true);}
function allEventsOverview(){return `<div class="ops-grid">${events.map(d=>{const e=state().events[d.id]||data.eventTemplate;return `<button class="ops-card ops-event" data-open-event="${d.id}"><span class="kicker">${esc(data.stages[e.stage]||'Completed')}</span><h3>${esc(eventName(d.id))}</h3><span>${d.payload.guests} guests · ${esc(d.payload.details.date||'Date undecided')}</span><span>${esc(e.owner||'Owner needed')}</span><small>${e.stage<8?esc(data.checklist[e.stage].find((_,i)=>!e.tasks[e.stage][i].done)||'Ready to advance'):esc(closeoutLabel(data.financials[d.id]))}${e.due?' · Due '+esc(date(e.due)):''}</small></button>`;}).join('')}</div>`;}
function overview(){const items=workItems(events,state(),data.eventTemplate),open=events.filter(d=>(state().events[d.id]?.stage??0)<8);return `<div class="today-heading"><div><p class="kicker">YOUR WORK QUEUE</p><h2>Today & next actions</h2><p class="muted">${esc(new Date().toLocaleDateString(undefined,{dateStyle:'full'}))} · ${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}. Undated events stay in planning.</p></div></div><div class="ops-grid">${metric('Open events',open.length,'Planning through reconciliation')}${metric('Return loads',state().reservations.filter(r=>r.status==='dispatched').length,'Currently away from the office')}${metric('Need attention',items.length,'Prioritized below')}${metric('Stock to count',state().inventory.length?state().inventory.filter(x=>x.quantity===null).length:state().openingStockZero?0:'Not set up','Unknown counts cannot be reserved')}</div><div class="work-queue">${items.map(x=>`<button class="work-item" data-open-event="${esc(x.id)}"><span><span class="kicker">${esc(x.label)}</span><strong>${esc(eventName(x.id))}</strong><small>${esc(x.eventDate||'Date undecided')}${x.due?' · Deadline '+esc(date(x.due)):''}</small><small>${esc(x.reasons.slice(1).join(' · '))}</small></span><span class="work-action">${esc(x.action)} →</span></button>`).join('')||'<p class="ops-card">No flagged actions. Review your events below for upcoming work.</p>'}</div><h2>All events</h2><label>Find an event<input type="search" id="event-search" placeholder="Search name, owner, date or stage"></label><label>Event status<select id="event-filter"><option value="all">All events</option><option value="open">Open events</option><option value="closed">Completed events</option></select></label><div id="all-events">${allEventsOverview()}</div>`;}
function focusStage(){const stage=ev().stage,step=viewStep??flowStep(stage);document.querySelector('.ops').classList.add('event-mode');const sections=[...document.querySelectorAll('#content > details:not(.client-brief)')];const keys=['finance','planning','staff','stock','orders','activity'];sections.forEach((el,i)=>{el.dataset.section=keys[i];const relevant=flowSections[step].includes(keys[i]);el.hidden=stage!==8&&!showAllDetails&&!relevant;el.open=stage!==8&&relevant;});const finance=sections[0];finance.querySelector('summary').textContent=step===0?'Owner & agreed price':step===1?'Planned costs':'Costs, hours & payments';
if(ev().inventoryCosting){for(const name of ['stockUsed','leftover']){const input=finance.querySelector('[name='+name+']');if(input)input.closest('label').hidden=true;}}const plan=sections.find(x=>x.dataset.section==='planning');if(plan)plan.querySelector('summary').textContent=step===1?'Menu & quantities':step===2?'Pack the equipment':'Service plan';const stockSec=sections.find(x=>x.dataset.section==='stock');if(stockSec&&step===2)stockSec.querySelector('summary').textContent='Dispatch the load';
if(step===4){const stock=sections.find(x=>x.dataset.section==='stock');if(stock){stock.querySelector('summary').textContent='Receive the load';const forms=[...stock.querySelectorAll('.return-form')];const intro=document.createElement('p');intro.className='alert';intro.textContent=forms.length?forms.length+' load(s) to receive.':'Nothing left to receive. Release unused reservations.';stock.querySelector('summary').after(intro);for(const form of forms)intro.after(form.closest('section'));const other=document.createElement('details');other.innerHTML='<summary>Needs & new reservations</summary>';[...stock.children].filter(x=>!['SUMMARY','SECTION'].includes(x.tagName)&&x!==intro).forEach(x=>other.append(x));stock.append(other);}}
const order=flowSections[step];const footer=$('#flow-next');for(const key of order){const el=sections.find(x=>x.dataset.section===key);if(el)footer.before(el);}for(const el of sections.filter(x=>!order.includes(x.dataset.section)))footer.before(el);
 // Wizard presentation: a step header card, one full card per section of this step, then the confirm card.
 if(stage!==8&&!showAllDetails){const e=ev(),current=flowStep(stage),wrap=document.createElement('div');wrap.className='wizard';footer.before(wrap);
const stepStagesAll=data.stages.map((_,i)=>i).filter(i=>flowStep(i)===flowStep(stage));const total=stepStagesAll.reduce((n,i)=>n+data.checklist[i].length,0),done=stepStagesAll.reduce((n,i)=>n+e.tasks[i].filter(t=>t.done).length,0),progress=Math.round(((current+(total?done/total:0))/flowSteps.length)*100);
const head=document.createElement('div');head.className='wizard-card wizard-head';const intro=document.querySelector('.flow-intro');if(intro)head.append(intro);
const status=document.createElement('p');status.className='wizard-status';status.textContent=step<current?'Completed · still editable':step>current?'Upcoming · preview only':done===total?'All checkpoints confirmed':`${done} of ${total} checkpoints`;head.append(status);
const bar=document.createElement('div');bar.className='wizard-progress';bar.setAttribute('role','progressbar');bar.setAttribute('aria-valuenow',String(progress));bar.setAttribute('aria-valuemin','0');bar.setAttribute('aria-valuemax','100');bar.setAttribute('aria-label','Event progress');bar.innerHTML=`<span style="width:${progress}%"></span>`;head.append(bar);wrap.append(head);
const relevant=order.map(k=>sections.find(x=>x.dataset.section===k)).filter(Boolean);
const last=relevant.length;if(viewSection==='confirm'||viewSection>last)viewSection=last;if(viewSection<0)viewSection=0;const active=Math.min(viewSection,last);relevant.forEach((el,i)=>{const card=document.createElement('section');card.className='wizard-card section-card';card.dataset.card=i;card.hidden=i!==active;const title=el.querySelector('summary')?.textContent||'';card.innerHTML=`<div class="section-head"><span class="section-index" aria-hidden="true">${step+1}.${i+1}</span><h3>${esc(title)}</h3><span class="section-count">Part ${i+1} of ${last}</span></div>`;el.open=true;card.append(el);const foot=document.createElement('div');foot.className='flash-nav';foot.innerHTML=`<button type="button" class="secondary" data-card-go="${i-1}" ${i===0?'disabled':''}>← Previous</button><span class="flash-dots" aria-label="Parts of this step">${relevant.map((_,j)=>`<button type="button" data-card-go="${j}" aria-label="Part ${j+1}" aria-current="${j===i?'true':'false'}"></button>`).join('')}<button type="button" data-card-go="${last}" aria-label="Confirm this step" aria-current="false" class="dot-confirm"></button></span><button type="button" data-card-go="${i+1}">${i+1<last?'Next: '+esc(relevant[i+1].querySelector('summary')?.textContent||'')+' →':'Confirm this step →'}</button>`;card.append(foot);wrap.append(card);});footer.hidden=active!==last;const gapCard=text=>{const t=text.toLowerCase();const key=/owner|revenue|planned cost|staffing|actual expenses|client balance|payments/.test(t)?'finance':/menu|ingredient|quantit/.test(t)?'planning':/load|reservation|dispatch|receive|inventory/.test(t)?'stock':/order|supplier/.test(t)?'orders':null;const i=key?order.indexOf(key):-1;return i>=0?i:null;};const detail=text=>/planned cost/.test(text.toLowerCase())?(()=>{const e2=ev(),blank=e2.expenses.filter(x=>x.plannedCents===null).map(x=>x.name);const extra=e2.staffingConfirmed?[]:['Staffing reviewed checkbox'];const all=[...blank,...extra];return all.length?` <small class="muted">Blank: ${esc(all.join(', '))}</small>`:'';})():'';footer.querySelectorAll('.alert li').forEach(li=>{const i=gapCard(li.textContent);li.insertAdjacentHTML('beforeend',detail(li.textContent)+(i!==null?` <button type="button" class="gap-go" data-card-go="${i}">Go to part ${i+1}: ${esc(relevant[i].querySelector('summary')?.textContent||'')} →</button>`:/Prepare step/.test(li.textContent)&&step!==1?' <button type="button" class="gap-go" data-flow-step="1">Go to the Prepare step →</button>':''));});
const nav=document.createElement('div');nav.className='wizard-nav';nav.innerHTML=(last?`<button type="button" class="secondary" data-card-go="${last-1}">← Back to part ${last}</button>`:'')+(step>0?` <button type="button" class="secondary" data-flow-step="${step-1}">← ${esc(flowSteps[step-1])} step</button>`:'');if(nav.innerHTML.trim())footer.prepend(nav);footer.classList.add('wizard-card','confirm-card');wrap.append(footer);}
}
function filterEvents(){const query=$('#event-search').value.toLowerCase(),filter=$('#event-filter').value;document.querySelectorAll('#all-events [data-open-event]').forEach(card=>{const closed=(state().events[card.dataset.openEvent]?.stage??0)===8;card.hidden=!card.textContent.toLowerCase().includes(query)||(filter==='open'&&closed)||(filter==='closed'&&!closed);});}
function eventView(){const e=ev(),d=eventDoc(),f=data.financials[selected],closed=e.stage===8,current=flowStep(e.stage),step=viewStep??current;const gaps=[...recordGaps(e,f,state().reservations.filter(x=>x.eventId===selected)),...prepGaps(e)];const stepStages=closed?[]:data.stages.map((_,i)=>i).filter(i=>flowStep(i)===current&&i>=e.stage);return `<button data-overview>← All events</button><div class="event-title"><h2>${esc(eventName(selected))}</h2></div><a class="prep-link" href="/admin/event.html?event=${encodeURIComponent(selected)}">Edit event details →</a> <a class="prep-link" href="/admin/proposal.html?event=${encodeURIComponent(selected)}">Proposal →</a>${e.agreementNeedsReview?'<p class="notice">Event scope changed. Accept a revised proposal before continuing.</p>':''}${e.acceptedProposalRevision?`<p class="notice">Accepted proposal r${e.acceptedProposalRevision} · Revenue ${usd(e.revenueCents)} · Tax ${usd(e.salesTaxCents)} · Client total ${usd(e.invoiceTotalCents)}</p>`:''}${e.acceptedScope?`<details class="client-brief"><summary>Accepted service brief · r${e.acceptedProposalRevision}</summary><p>Load-in ${esc(e.acceptedScope.loadIn)} · Departure ${esc(e.acceptedScope.departure)}</p><p style="white-space:pre-wrap">${esc(e.acceptedScope.scope)}</p><p style="white-space:pre-wrap">${esc(e.acceptedScope.terms)}</p><p>Deposit ${usd(e.acceptedScope.depositCents)} due ${esc(e.acceptedScope.depositDue)} · Balance ${usd(e.acceptedScope.balanceCents)} due ${esc(e.acceptedScope.balanceDue)}</p></details>`:''}<div class="event-summary"><span><strong>${d.payload.guests} guests</strong>${esc(d.payload.details.date||'Date to confirm')}</span><span><strong>${esc(d.payload.details.venue||'Venue to confirm')}</strong>${esc(d.payload.details.startTime||'Time to confirm')}</span><span><strong>${usd(f?.plannedComplete?f.planned:null)}</strong>${f?.plannedComplete?'Planned cost':'Planned cost incomplete'+(f?.planned?' · '+usd(f.planned)+' so far':'')}</span><span><strong>${usd(f?.profit)}</strong>Actual profit</span></div><nav class="flow-steps" aria-label="Event steps">${flowSteps.map((name,i)=>`<button data-flow-step="${i}" aria-current="${i===step?'step':'false'}" data-upcoming="${!closed&&i>current}" title="${closed||i<current?'Review this completed step':i===current?'Current step':'Preview this upcoming step'}"><span>${closed||i<current?'✓':i+1}</span>${esc(name)}<small>${closed||i<current?'Completed':i===current?'Current':'Upcoming'}</small></button>`).join('')}</nav><section class="flow-intro"><p class="kicker">STEP ${step+1} OF 5</p><h2>${esc(flowSteps[step])}</h2><p>${['Name the owner. Confirm the agreed price.','Confirm the menu and quantities, assign staff, reserve stock, set planned costs.','Buy what is missing, pack the equipment, dispatch the load.','Arrive, set up, serve, clean up.','Receive the load, record hours and actual costs, settle the client balance.'][step]}</p>${step!==current&&!closed?'<p class="alert">Reviewing another step. The event is at '+esc(data.stages[e.stage])+'.</p>':''}</section><details class="client-brief"><summary>Client & venue · ${esc(d.labels.menus.join(', ')||'Menu undecided')}</summary><p>${esc(d.payload.details.name)} · ${esc(d.payload.details.email)}</p><p>${esc(d.payload.details.venue||'Venue unconfirmed')} · ${esc(d.payload.details.city)}</p><p>Access / restrictions: ${esc(d.payload.details.restrictions||'None entered')}</p><a href="/admin">Inquiry desk ↗</a></details><div class="inline-actions"><button data-show-details aria-expanded="${showAllDetails}">${showAllDetails?'Focus on this step':'Show all event details'}</button></div>${financialForm(e,f,step)+planningForm(step)+staffingView(e)+reservationView(step)+ordersView(e)}<details><summary>Event activity</summary>${activityView(selected)}</details><section id="flow-next" class="ops-card"><p class="kicker">${closed?'EVENT COMPLETED':step===current?'NEXT ACTION':'CURRENT PROGRESS'}</p><h3>${esc(data.stages[e.stage]||closeoutLabel(f))}</h3>${closed?'<p>Return complete. Costs and payments stay editable below.</p><button data-reopen>Reopen reconciliation</button>':step!==current?'<button data-current-step>Return to current step →</button>':`${gaps.length?'<div class="alert"><strong>Still needed</strong><ul>'+gaps.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul></div>':''}${stepStages.map(s=>`${stepStages.length>1?`<p class="kicker">${esc(data.stages[s])}</p>`:''}${e.tasks[s].map((t,i)=>`<label class="task"><input type="checkbox" ${s===e.stage?`data-task="${i}"`:`data-task-ahead="${i}"`} data-stage="${s}" ${t.done?'checked':''}><span>${esc(data.checklist[s][i])}${t.done?`<small>${esc(t.by)} · ${esc(date(t.at))}</small>`:''}</span></label>`).join('')}`).join('')}<button data-advance>${current===4?'Close event':'Continue'} →</button>`}</section>`;}
function planningForm(step){if(!prep?.plan)return '<details><summary>Preparation unavailable</summary><p>Refresh to load the plan.</p></details>';const p=prep.plan,x=prep.summary,full=showAllDetails||ev().stage===8,blank=x.equipment.filter(q=>q.quantity===null).map(q=>q.name),prepare=step===1||full,pack=step===2||full,run=step===3&&!full;const head=`<p><strong>${esc(eventDoc().labels.menus.join(', ')||'Menu to confirm')}</strong> · ${x.totalDrinks??'?'} drinks · ${p.machines} machine${p.machines===1?'':'s'} · ${x.packed}/${x.equipment.length} packed</p>${x.complete?'':'<p class="alert">Incomplete: confirm the menu, recipes and quantities.</p>'}${(x.catalogWarnings||[]).map(w=>`<p class="alert">${esc(w)}</p>`).join('')}`;if(run)return `<details><summary>Service plan</summary>${head}<div class="ops-grid">${p.recipes.map((r,i)=>`<div class="ops-card"><h3>${esc(r.name)}</h3><p>${x.servings[i]?.count??'?'} servings</p><p class="muted">${esc(r.ingredients.map(z=>`${z.name} ${z.amount} ${z.unit}`).join(' · '))}</p></div>`).join('')}</div><p>${x.equipment.map(q=>`${esc(q.name)} ×${q.quantity??'?'}${q.packed?' ✓':''}`).join(' · ')}</p></details>`;return `<details><summary>Menu, quantities & equipment</summary>${head}<form id="flow-prep" class="ops-form"><div ${prepare?'':'hidden'}><div class="ops-grid">${field('Drinks per guest','drinks',p.drinksPerGuest??'','number','min="0.1" max="20" step="0.1"')}${field('Buffer %','buffer',p.bufferPercent,'number','min="0" max="100"')}${field('360 machines','machines',p.machines,'number',`min="${x.minimumMachines}" max="1000" required`)}</div>${check('Client menu confirmed','menuConfirmed',p.menuConfirmed)}<details><summary>Recipes & demand split (${p.recipes.length})</summary>${p.recipes.map((r,i)=>`<div class="ops-card" data-flow-recipe="${i}"><h3>${esc(r.name)}</h3><p>${x.servings[i]?.count??'?'} servings</p>${r.reviewNote?`<p class="alert">${esc(r.reviewNote)}</p>`:''}${field('Demand weight','share-'+i,r.share,'number','min="0" max="100" step="0.1" required')}<label>Ingredients · name | amount | unit<textarea name="ingredients-${i}" rows="4">${esc(r.ingredients.map(z=>[z.name,z.amount,z.unit].join(' | ')).join('\n'))}</textarea></label>${check('Measurements confirmed','confirmed-'+i,r.confirmed)}</div>`).join('')}</details></div><details${pack||blank.length?' open':''}><summary>Equipment${pack?' · tick each item as packed':''}</summary>${blank.length?`<p class="alert">Enter a quantity for ${esc(blank.join(', '))}. Quantities lock once stock is reserved.</p>`:''}${x.equipment.map(q=>`<div class="packing-line"><span><strong>${esc(q.name)}</strong><small>${q.minimum===null?'Set quantity':q.minimum+' minimum'}</small></span>${field('Quantity','equipment-'+q.id,q.quantity??'','number',`min="${q.minimum??0}" max="10000" step="1" ${q.id==='machines'?'readonly':''}`)}<span ${pack?'':'hidden'}>${check('Packed','packed-'+q.id,q.packed)}</span></div>`).join('')}</details><button>Save</button></form>${prepare?`<p class="muted"><a href="/admin/preparation.html?event=${selected}">Price overrides & export ↗</a></p>`:''}</details>`;}
function financialForm(e,f,step){const full=showAllDetails||e.stage===8,confirm=step===0||full,plan=step===1||full,close=step===4||full,receipts=e.receiptFiles||[];return `<details><summary>Costs & payments</summary><form id="event-form" class="ops-form"><div ${confirm?'':'hidden'}><div class="ops-grid">${field('Event owner','owner',e.owner,'text','required maxlength="120"')}${field('Next action deadline','due',localTime(e.due),'datetime-local')}${field('Agreed revenue before tax, USD','revenue',e.revenueCents===null?'':e.revenueCents/100,'number','min="0" step="0.01"'+(e.acceptedProposalRevision?' readonly':''))}${field('Target margin %','target',e.targetMargin,'number','min="0" max="100" step="0.1"')}</div><label>Internal notes<textarea name="notes" maxlength="2000">${esc(e.notes)}</textarea></label></div><div ${plan||close?'':'hidden'}>${plan?`<div class="inline-actions"><button type="button" data-suggest-costs>Suggest planned costs</button><span class="muted">Fills blank planned figures from the buy list, stock value and card fees. Typed values stay.</span></div>`:''}${close&&receipts.length?`<div class="inline-actions receipt-fill"><button type="button" data-fill-receipts>Fill actual paid from receipts</button><label>into<select name="receiptCategory">${e.expenses.map((x,i)=>`<option value="${i}" ${x.name==='Spirits, mixers & ingredients'?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><span class="muted">${receipts.length} receipt(s) · ${usd(receipts.reduce((n,x)=>n+x.amountCents,0))}</span></div>`:''}<div class="ops-table"><table><thead><tr><th>Cost</th><th>Planned USD</th><th ${close?'':'hidden'}>Actual paid USD</th><th>Reference / note</th></tr></thead><tbody>${e.expenses.map((x,i)=>`<tr><th>${esc(x.name)}</th><td>${dollarInput('planned-'+i,x.plannedCents)}</td><td ${close?'':'hidden'}>${dollarInput('actual-'+i,x.actualCents)}</td><td><input aria-label="${esc(x.name)} reference" name="note-${i}" value="${esc(x.note)}" maxlength="500"></td></tr>`).join('')}<tr><th>Staff (hours × rate)</th><td>${usd(f?.plannedStaff)}</td><td ${close?'':'hidden'}>${usd(f?.actualStaff)}</td><td></td></tr></tbody></table></div><p class="muted">Blank = unknown. Enter 0 only when confirmed.</p></div><div ${close?'':'hidden'}><div class="ops-grid">${field('Office stock sent, at cost USD','stockUsed',e.stockUsedCents===null?'':e.stockUsedCents/100,'number','min="0" step="0.01"')}${field('Reusable stock returned, at cost USD','leftover',e.leftoverCents===null?'':e.leftoverCents/100,'number','min="0" step="0.01"')}</div>${e.inventoryCosting?`<p class="alert">Stock costs come from dispatch and return records: sent ${usd(f?.ledger?.issuedCents)}, returned ${usd(f?.ledger?.returnedCents)}, equipment losses ${usd(f?.ledger?.equipmentLossCents)}. Purchases paid ${usd(f?.ledger?.purchasePaidCents)}, supplier balance ${usd(f?.ledger?.purchaseUnpaidCents)}. Do not enter received inventory again in the rows.</p>`:''}</div><div ${plan||close?'':'hidden'}>${check('Staffing reviewed (tick even with no staff)','staffingConfirmed',e.staffingConfirmed)}</div><div ${close?'':'hidden'}>${check('Actual staff hours reviewed','actualHoursConfirmed',e.actualHoursConfirmed)}</div>${plan&&!close?`<p>Planned cost ${usd(f?.planned)} · Budget ${usd(f?.budget)} · Planned profit ${usd(f?.plannedProfit)}</p>`:close?`<p>Cash paid ${usd(f?.cash)} · Consumed ${usd(f?.consumed)}${f?.actualComplete?'':' (incomplete)'} · Profit ${usd(f?.profit)}</p>`:''}<button>Save</button></form>${confirm||close?paymentForm(e,f):''}</details>`;}
// Default staffing/stock window from the event: load-in (accepted scope, else one hour before service) to departure (accepted scope, else one hour after service ends).
function defaultWindow(){try{const d=eventDoc(),e=ev(),det=d.payload.details;if(!det.date)return {start:'',end:'',hours:''};const hm=t=>/^\d\d:\d\d$/.test(t||'')?t:null;const shift=(t,h)=>{const [H,M]=t.split(':').map(Number);const m=Math.min(Math.max(H*60+M+h*60,0),23*60+59);return String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0');};const svc=hm(det.startTime)||'17:00',hours=Number(d.payload.serviceHours)||2;const start=hm(e.acceptedScope?.loadIn)||shift(svc,-1),end=hm(e.acceptedScope?.departure)||shift(svc,hours+1);const mins=t=>{const [H,M]=t.split(':').map(Number);return H*60+M;};const span=Math.max(0,(mins(end)-mins(start))/60);return {start:det.date+'T'+start,end:det.date+'T'+end,hours:span?String(Math.round(span*4)/4):''};}catch{return {start:'',end:'',hours:''};}}
function staffingView(e){return `<details><summary>Staff & hours (${e.staffing.length})</summary><p class="muted">Times in ${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}, prefilled from load-in and departure. Overlapping assignments are blocked.</p>${e.staffing.map(x=>`<form class="assignment ops-form" data-id="${x.id}"><h3>${esc(x.name)} · ${x.internal||x.rateCents===0?'Barsys team · no labor cost':usd(x.rateCents)+'/hour'}</h3><input type="hidden" name="staffId" value="${x.staffId}"><div class="ops-grid">${field('Role','role',x.role)}${field('Start','start',localTime(x.start),'datetime-local','required')}${field('End','end',localTime(x.end),'datetime-local','required')}${field('Planned hours','plannedHours',x.plannedHours,'number','min="0" max="500" step="0.25" required')}${field('Actual hours','actualHours',x.actualHours??'','number','min="0" max="500" step="0.25"')}</div><button>Save</button>${x.actualHours===null?`<button type="button" data-unassign="${x.id}">Remove</button>`:''}</form>`).join('')}<form id="assign-form" class="ops-form"><h3>Assign staff</h3><label>Staff<select name="staffId" required><option value="">Choose from directory</option>${state().staff.filter(x=>x.active).map(x=>`<option value="${x.id}">${esc(x.name)} · ${x.internal?'Barsys team · no labor cost':usd(x.rateCents)+'/hour'}</option>`).join('')}</select></label><div class="ops-grid">${(()=>{const w=defaultWindow();return field('Role','role','','text','required')+field('Start','start',w.start,'datetime-local','required')+field('End (incl. office return)','end',w.end,'datetime-local','required')+field('Planned hours','plannedHours',w.hours,'number','min="0" max="500" step="0.25" required');})()}</div><button>Assign</button></form></details>`;}
// Inventory matching for the shortage table: exact name+unit first, then a name-token match with bottle/oz units converted to ml.
const ML_PER_OZ=29.5735;
function inventoryMl(x){const u=String(x.unit||'').trim().toLowerCase().replace(/^70z$/,'7oz');let m;if(x.unit==='ml')return 1;if((m=/^(\d+(?:\.\d+)?)\s*ml$/.exec(u)))return Number(m[1]);if((m=/^(\d+(?:\.\d+)?)\s*(oz|fl ?oz)$/.exec(u)))return Number(m[1])*ML_PER_OZ;if((m=/^(\d+(?:\.\d+)?)\s*l$/.exec(u)))return Number(m[1])*1000;if(/^(bottle|btl|750)$/.test(u))return 750;return null;}
function nameMatches(inv,ing){const a=inv.toLowerCase(),b=ing.toLowerCase();if(a===b)return true;const alias=[['cointreau','triple sec'],['lime juice','fresh lime juice'],['cranberry','cranberry juice'],['oj','orange juice'],['vermouth','vermouth di torino'],['sweet vermouth','vermouth di torino']];const tokens=a.split(/[\s\/,]+/).filter(t=>t.length>2);if(tokens.length&&tokens.every(t=>b.includes(t)))return true;if(b.split(/\s+/).filter(t=>t.length>2).every(t=>a.includes(t)))return true;return alias.some(([x,y])=>(a.includes(x)&&b.includes(y))||(a.includes(y)&&b.includes(x)));}
// Fuzzy inventory matcher shared with purchaseNeeds(): name tokens plus bottle/oz → ml conversion.
const fuzzyMatcher=(row,st)=>{const matches=st.inventory.filter(x=>x.kind==='consumable'&&nameMatches(x.name,row.name)&&(row.unit==='ml'?inventoryMl(x)!==null:x.unit===row.unit));return {matches,factor:x=>row.unit==='ml'?(inventoryMl(x)||0):1};};
function shortageRows(){const rows=prep?.summary.ingredients||[],purchases=prep?.summary.costs?.purchases||[];return rows.map(r=>{const buy=purchases.find(p=>p.ingredients.includes(r.name))||null;const exact=state().inventory.filter(x=>x.kind==='consumable'&&x.unit===r.unit&&x.name.toLowerCase()===r.name.toLowerCase());const fuzzy=exact.length?[]:state().inventory.filter(x=>x.kind==='consumable'&&nameMatches(x.name,r.name)&&(r.unit==='ml'?inventoryMl(x)!==null:x.unit===r.unit));const matches=exact.length?exact:fuzzy,factor=x=>exact.length||r.unit!=='ml'?1:inventoryMl(x);const known=matches.length?matches.every(x=>x.quantity!==null):!!state().openingStockZero;const reservedFor=x=>state().reservations.filter(a=>a.itemId===x.id&&a.status==='reserved').reduce((v,a)=>v+a.quantity,0);const alloc=matches.reduce((n,x)=>n+state().reservations.filter(a=>a.itemId===x.id&&a.eventId===selected&&['reserved','dispatched'].includes(a.status)).reduce((v,a)=>v+a.quantity*factor(x),0),0),free=matches.reduce((n,x)=>n+(x.condition==='ready'?((x.quantity??0)-reservedFor(x))*factor(x):0),0);const short=known?Math.max(0,r.amount-free-alloc):null;const reserve=matches.filter(x=>x.quantity!==null&&x.condition==='ready').map(x=>({item:x,units:Math.min(Math.max(0,x.quantity-reservedFor(x)),Math.ceil((Math.max(0,r.amount-alloc))/factor(x)-1e-9)),perUnitMl:factor(x)}));return {r,buy,exact,fuzzy,matches,known,alloc,free,short,reserve};});}
function gopuffLines(){return shortageRows().filter(x=>(x.short===null||x.short>0)&&!keywordIn(x.r.name.toLowerCase(),SPIRIT_KEYWORDS)).map(x=>{const need=x.short===null?x.r.amount:x.short,packs=x.buy?Math.ceil(need/x.buy.packAmount-1e-9):null;return {name:x.r.name,need:Math.ceil(need),unit:x.r.unit,packs,pack:x.buy?Math.round(x.buy.packAmount)+' '+x.buy.unit:null,product:x.buy?.product||null,cents:x.buy&&packs?packs*x.buy.priceCents:null};});}
function gopuffMessage(){const d=eventDoc(),lines=gopuffLines();return `Gopuff order for ${d.payload.details.company||d.payload.details.name} — ${d.payload.details.date||'date TBC'} (${d.payload.guests} guests):\n`+lines.map(l=>`• ${l.name}: ${l.need} ${l.unit} short → ${l.packs?l.packs+' × '+l.pack+(l.product?' ('+l.product+')':''):'quantity TBC'}${l.cents!=null?' ≈ $'+(l.cents/100).toFixed(2):''}`).join('\n')+`\nTotal ≈ $${(lines.reduce((n,l)=>n+(l.cents||0),0)/100).toFixed(2)} before tax/delivery. Sent from the Barsys operations dashboard.`;}
function shoppingList(){const rows=shortageRows();if(!rows.length)return '';const toBuy=rows.filter(x=>x.short===null||x.short>0),spirits=toBuy.filter(x=>keywordIn(x.r.name.toLowerCase(),SPIRIT_KEYWORDS)),others=toBuy.filter(x=>!spirits.includes(x)),reserve=rows.filter(x=>x.known&&x.alloc<x.r.amount&&x.reserve.some(v=>v.units>0));const line=x=>{const need=x.short===null?x.r.amount:x.short;const packs=x.buy?Math.ceil(need/x.buy.packAmount-1e-9):null;return `<li><strong>${esc(x.r.name)}</strong> — ${x.short===null?'not in counted stock':'short'} ${Math.ceil(need)} ${esc(x.r.unit)}${packs?` · ${packs} × ${Math.round(x.buy.packAmount)} ${esc(x.buy.unit)}${x.buy.product?' ('+esc(x.buy.product)+')':''} ≈ ${usd(packs*x.buy.priceCents)}`:' · no price on file'}</li>`;};const sum=list=>usd(list.reduce((n,x)=>n+(x.buy?Math.ceil((x.short===null?x.r.amount:x.short)/x.buy.packAmount-1e-9)*x.buy.priceCents:0),0));return `<section class="ops-card shopping-list"><h3>Event recommendation</h3>${toBuy.length?'':'<p><strong>Nothing to buy.</strong> Counted office stock covers every ingredient for this menu.</p>'}${spirits.length?`<p><strong>Spirits to order — Astor Wines (${spirits.length}) ≈ ${sum(spirits)}</strong></p><ul>${spirits.map(line).join('')}</ul><p class="muted">Use the supplier draft in the Purchase & pack step; it is prefilled from these lines.</p>`:''}${others.length?`<p><strong>Mixers, syrups & consumables — Gopuff (${others.length}) ≈ ${sum(others)}</strong></p><ul>${others.map(line).join('')}</ul><div class="inline-actions"><button type="button" data-slack-gopuff>Ping Fareed on Slack to order from Gopuff</button><button type="button" class="secondary" data-copy-gopuff>Copy Gopuff list</button></div>`:''}${reserve.length?`<p><strong>Reserve from office stock (${reserve.length})</strong></p><ul>${reserve.map(x=>`<li><strong>${esc(x.r.name)}</strong> — ${Math.ceil(x.r.amount)} ${esc(x.r.unit)} needed → reserve ${x.reserve.filter(v=>v.units>0).map(v=>`${v.units} × ${esc(v.item.unit)} of ${esc(v.item.name)}`).join(' + ')}</li>`).join('')}</ul><p class="muted">Use the reservation form with these quantities; reserved stock counts toward coverage and is dispatched at Purchase & pack.</p>`:''}</section>`;}
function shortagesView(){const rows=shortageRows();return `<h3>Needs vs counted stock</h3><p class="muted">Whole packs at saved prices, before tax and delivery. Bottle and oz stock convert to ml; unknown counts are never treated as zero.</p><div class="ops-table needs-table"><table><thead><tr><th>Ingredient</th><th>Needed</th><th>Pack · unit price</th><th>Packs to buy</th><th>Est. cost</th><th>On hand (matched)</th><th>Shortage</th></tr></thead><tbody>${rows.map(({r,buy,fuzzy,known,free,short})=>{const onHand=!known?'<span class="muted">Unknown / unmatched</span>':`${Math.round(free)} ${esc(r.unit)}${fuzzy.length?' <small class="muted">via '+esc(fuzzy.map(x=>x.name+' ('+x.quantity+' '+x.unit+')').join(', '))+'</small>':''}`;return `<tr><th>${esc(r.name)}</th><td>${r.amount} ${esc(r.unit)}</td><td>${buy?esc(Math.round(buy.packAmount)+' '+buy.unit)+' · '+usd(buy.priceCents)+(buy.ingredients.length>1?' <small class="muted">shared: '+esc(buy.ingredients.filter(n=>n!==r.name).join(', '))+'</small>':''):'<span class="muted">No price on file</span>'}</td><td>${buy?buy.packs:'—'}</td><td>${buy?usd(buy.purchaseCents):'—'}</td><td>${onHand}</td><td>${short===null?'Count / match first':short===0?'<strong>Covered</strong>':short.toFixed(0)+' '+esc(r.unit)+(buy?' · '+Math.ceil(short/buy.packAmount-1e-9)+' pack(s)':'')}</td></tr>`;}).join('')}</tbody></table></div>${shoppingList()}`;}
function reservationView(step){const all=state().reservations.filter(r=>r.eventId===selected),list=all.filter(r=>r.status!=='released'),released=all.filter(r=>r.status==='released'),full=showAllDetails||ev().stage===8,dispatchOnly=step===2&&!full;const blankEquipment=(prep?.summary?.equipment||[]).filter(q=>q.quantity===null).map(q=>q.name);const rows=list.map(r=>{const item=state().inventory.find(x=>x.id===r.itemId);return `<section class="ops-card"><h3>${esc(item.name)} · ${r.quantity} ${esc(item.unit)}</h3><p>${esc(r.status)} · ${esc(date(r.start))} → ${esc(date(r.end))}</p>${r.status==='reserved'?`<button data-dispatch="${r.id}">Mark dispatched</button> <button data-release="${r.id}">Release</button>`:r.status==='dispatched'?`<form class="return-form ops-form" data-id="${r.id}">${item.kind==='equipment'?`<div class="return-actions">${[['ready','Returned & ready'],['cleaning','Needs cleaning'],['charging','Needs charging'],['repair','Needs repair'],['missing','Missing']].map(([action,label])=>`<button type="button" data-return-preset="${action}">${label}</button>`).join('')}</div>`:''}<div class="ops-grid">${field('Usable quantity returned','returned','','number','required min="0" step="0.001"')}${field('Lost / discarded','lost',0,'number','required min="0" step="0.001"')}<label>Condition<select name="condition">${['ready','cleaning','charging','repair'].map(x=>`<option>${x}</option>`).join('')}</select></label></div>${field('Notes','note','','text','maxlength="500"')}<button>Receive</button></form>`:r.status==='returned'?`<p>Returned ${r.returned} · lost ${r.lost} · consumed ${r.consumed} · ${esc(r.receivedBy)}${r.note?' · '+esc(r.note):''}</p>`:''}</section>`;}).join('');const reserveForm=`<form id="reserve-form" class="ops-form"><h3>Reserve counted inventory</h3><label>Item<select name="itemId" required><option value="">Select stock or equipment</option>${state().inventory.map(x=>`<option value="${x.id}">${esc(x.name)} · ${x.quantity===null?'Unknown stock':x.quantity+' '+esc(x.unit)+' on hand'} · ${esc(x.condition)}</option>`).join('')}</select></label><div class="ops-grid">${(()=>{const w=defaultWindow();return field('Quantity','quantity','','number','required min="0.001" step="0.001"')+field('Office departure','start',w.start,'datetime-local','required')+field('Expected return','end',w.end,'datetime-local','required');})()}</div><button>Reserve</button></form>`;return `<details><summary>Stock: needs & reservations (${list.filter(x=>!['released','returned'].includes(x.status)).length} open)</summary>${dispatchOnly?`${rows||'<p class="muted">Nothing reserved for this event.</p>'}<details><summary>Needs & new reservations</summary>${shortagesView()}${reserveForm}</details>`:`${blankEquipment.length&&ev().stage<3?`<p class="alert">Before reserving, enter quantities for ${esc(blankEquipment.join(', '))} on the menu card; they lock once stock is reserved.</p>`:''}${shortagesView()}${rows}${reserveForm}`}${released.length?`<details><summary>Released reservations (${released.length})</summary>${released.map(r=>{const item=state().inventory.find(x=>x.id===r.itemId);return `<p class="muted">${esc(item?.name)} · ${r.quantity} ${esc(item?.unit)} · ${esc(date(r.start))} → ${esc(date(r.end))}</p>`;}).join('')}</details>`:''}</details>`;}
function ordersView(e){return `<details><summary>Buy, receipts & suppliers (${(e.orders||[]).length})</summary>${receiptForm(e)}${supplierDraft()}${[...(e.orders||[]),{id:'',supplier:'Astor Wines & Spirits',status:'draft',reference:'',amountCents:null,notes:''}].map(x=>`<form class="order-form ops-form ops-card" data-id="${x.id}"><h3>${x.id?'Supplier record':'Add supplier record'}</h3><div class="ops-grid">${field('Supplier','supplier',x.supplier,'text','required maxlength="200"')}${field('Order / invoice reference','reference',x.reference,'text','maxlength="200"')}<label>Status<select name="status">${['draft','requested','confirmed','received','cancelled'].map(v=>`<option ${v===x.status?'selected':''}>${v}</option>`).join('')}</select></label>${field('Quoted / invoiced USD','amount',x.amountCents===null?'':x.amountCents/100,'number','min="0" step="0.01"')}</div><label>Notes<textarea name="notes" maxlength="2000">${esc(x.notes)}</textarea></label><button>Save</button></form>`).join('')}</details>`;}
function supplierDraft(){const d=eventDoc(),c=prep?.summary.costs,needs=purchaseNeeds(c?.rows||[],state(),selected,fuzzyMatcher);const rows=needs.purchases.filter(x=>{try{return new URL(x.url).hostname==='www.astorwines.com';}catch{return false;}})||[];const text=['To: vpagan@astorwines.com','Subject: Quote request — '+eventName(selected),'','Please confirm availability, current pricing, taxes and delivery for this event. This is a quote request, not an order authorization.','Event: '+eventName(selected),'Date: '+(d.payload.details.date||'To confirm'),'Guests: '+d.payload.guests,'Venue: '+(d.payload.details.venue||'To confirm')+', '+d.payload.details.city,'Delivery date / address / access: PLEASE COMPLETE BEFORE SENDING','','Requested products:',...rows.map(x=>`${x.product} — ${x.packs} packs of ${x.packAmount} ${x.unit}; reference ${usd(x.priceCents)} each\n${x.url}`),'',`Planning status: ${c?.complete&&!needs.unresolved.length?'Measured estimate':'INCOMPLETE: confirm all recipes, prices and yields'}.`,'Quantities deduct counted office stock and current-event allocations. Confirm products, sizes and final quantities before sending.','Please reply with a quote and proposed delivery arrangements. Thank you.'].join('\n');return `<details><summary>Astor quote email (${rows.length} products)</summary><textarea id="supplier-draft" rows="12" style="width:100%">${esc(text)}</textarea><div class="inline-actions"><button data-email ${rows.length?'':'disabled'}>Open email draft</button><button data-download-draft>Download text</button></div><p class="muted">Nothing is sent automatically. Complete the delivery details first.</p></details>`;}
function countButtons(x){const t=data.inventoryTemplates.find(t=>t.name.toLowerCase()===x.name.toLowerCase()&&t.unit===x.unit),amount=x.kind==='equipment'?1:t?.packAmount||1;return `<div class="inline-actions"><button type="button" data-count-adjust="${-amount}">− ${amount===1?'1 '+esc(x.unit):'1 matching pack'}</button><button type="button" data-count-adjust="${amount}">+ ${amount===1?'1 '+esc(x.unit):'1 matching pack'}</button></div>${amount!==1?`<small>Matching pack: ${esc(t.product||x.name)} · ${esc(t.packLabel||amount+' '+x.unit)}. Save to confirm.</small>`:''}`;}
const SPIRIT_KEYWORDS=['tequila','mezcal','vodka','rum','whiskey','whisky','bourbon','gin','cognac','brandy','liqueur','vermouth','cointreau','triple sec','aperitif','sake','soju','cachaça','cachaca','pisco','absinthe','amaro','campari','aperol','sherry','port'];
const SUPPLY_KEYWORDS=['towel','wipe','cup','ice bag','napkin','straw','coaster','bar mat','trash bag','zip tie','sharpie','glove','apron','tape','tray','bin','bucket','sponge','cloth','paper'];
let inventoryCategory='ingredient';
const keywordIn=(name,keywords)=>keywords.some(k=>new RegExp('(^|[^a-z])'+k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(s|es)?($|[^a-z])').test(name));
function categoryOf(x){if(x.kind==='equipment')return 'equipment';const n=(x.name||'').toLowerCase();if(keywordIn(n,SUPPLY_KEYWORDS))return 'equipment';if(/non-alcoholic|zero-proof|alcohol-free/.test(n))return 'ingredient';return keywordIn(n,SPIRIT_KEYWORDS)?'spirit':'ingredient';}
function inventoryPicker(){const cats=[['ingredient','Ingredients'],['spirit','Spirits'],['equipment','Equipment'],['all','All items']];return `<section class="ops-card"><h3>Pick an item. Count what you have.</h3><p>Choose an ingredient from your mixlists or a standard equipment item. Names and units fill automatically; quantities stay unknown until counted.</p><div class="ops-subtabs" role="tablist" aria-label="Inventory category">${cats.map(([id,label])=>`<button type="button" role="tab" data-cat-tab="${id}" aria-selected="${inventoryCategory===id?'true':'false'}">${esc(label)}</button>`).join('')}</div><label>Find an item<input id="inventory-search" type="search" placeholder="Search tequila, juice, iPad… (searches every category)"></label><div class="picker-results" id="inventory-options">${pickerOptions('')}</div></section>`;}
function pickerOptions(query){const q=query.trim().toLowerCase();const labels={ingredient:'Ingredient',spirit:'Spirit',equipment:'Equipment'};const all=data.inventoryTemplates.map((x,i)=>({...x,index:i}));const scoped=(q||inventoryCategory==='all')?all:all.filter(x=>categoryOf(x)===inventoryCategory);const matches=scoped.filter(x=>(x.name+' '+(x.product||'')).toLowerCase().includes(q));const shown=matches.slice(0,30);return shown.map(x=>`<button type="button" data-pick-item="${x.index}"><strong>${esc(x.name)}</strong><small>${x.kind==='equipment'?'Equipment · auto asset label':esc(x.unit)}${x.product?' · '+esc(x.product):''}${(q||inventoryCategory==='all')?' · '+labels[categoryOf(x)]:''}</small></button>`).join('')+(matches.length>shown.length?`<p class="muted">Showing ${shown.length} of ${matches.length} matches. Keep typing to narrow the list.</p>`:'')||'<p>No match. Use the custom item form below.</p>';}
function inventoryView(){return `<h2>Inventory & equipment</h2><p>Start with counted office stock. Add each machine and iPad separately with its asset label. Receive purchases in the event’s Purchase & pack step to add stock and cost together. Use manual counts only for corrections and record the reason.</p>${state().openingStockZero?'<p class="alert">Opening stock confirmed as zero. Purchase receipts add quantities and cost to inventory.</p>':state().inventory.length?'':'<button data-opening-zero>Confirm empty opening inventory</button>'}${inventoryPicker()}<form id="inventory-form" class="ops-form ops-card"><h3 id="inventory-form-title">Or add a custom item</h3><p id="inventory-pick-note" class="muted"></p><div class="ops-grid">${field('Name / asset tag','name','','text','required maxlength="120"')}<label>Type<select name="kind"><option value="consumable">Ingredient / consumable</option><option value="equipment">Individual equipment asset</option></select></label>${field('Unit (bottle, ml, each)','unit','','text','required maxlength="30"')}${field('Counted quantity (blank = unknown)','quantity','','number','min="0" step="0.001"')}</div><div id="pack-counter" hidden></div><div class="inline-actions"><button type="button" data-inventory-count="0">None in stock</button><button type="button" data-inventory-count="1">Set count to 1</button><button type="button" data-inventory-count="">Count later</button></div>${field('Receipt / count notes','note','','text','maxlength="500"')}<button>Add inventory item</button></form><div class="ops-grid">${state().inventory.map(x=>`<form class="stock-form ops-card ops-form" data-id="${x.id}"><h3>${esc(x.name)}</h3><p>${esc(x.kind)} · ${esc(x.unit)} · ${x.quantity===null?'Not counted':'Counted '+esc(date(x.countedAt))}</p><input name="name" type="hidden" value="${esc(x.name)}">${field('Office quantity','quantity',x.quantity??'','number','min="0" step="0.001"')}${countButtons(x)}${field('Total office stock value USD (at cost)','stockValue',x.stockValueCents==null?'':x.stockValueCents/100,'number','min="0" step="0.01"')}<label>Condition<select name="condition">${['ready','cleaning','charging','repair'].map(v=>`<option ${v===x.condition?'selected':''}>${v}</option>`).join('')}</select></label>${field('Count / condition notes','note',x.note,'text','maxlength="500"')}<p>${state().reservations.filter(r=>r.itemId===x.id&&r.status==='reserved').map(r=>`Reserved ${r.quantity} for ${esc(eventName(r.eventId))} (${esc(date(r.start))})`).join('<br>')||'No reservations'}</p><button>Save count / condition</button></form>`).join('')}</div>`;}
function staffView(){return `<h2>Staff directory</h2><p>Assignments reserve availability across events. Default rate: $50/hour. Mark salaried Barsys team members as “no event labor cost” so their hours never add to an event's cost. Enable crew login explicitly on a saved staff record. Crew see only assigned events; owner financials stay private.</p><form id="staff-form" class="ops-form ops-card"><div class="ops-grid">${field('Name','name','','text','required maxlength="120"')}${field('Role','role','','text','required maxlength="120"')}${field('Hourly rate USD','rate',50,'number','min="0" step="0.01" required')}${check('Barsys team member — no event labor cost','internal',false)}</div><button>Add staff member</button></form><div class="ops-grid">${state().staff.map(x=>`<form class="staff-edit ops-card ops-form" data-id="${x.id}">${field('Name','name',x.name,'text','required maxlength="120"')}${field('Role','role',x.role,'text','maxlength="120"')}${field('Hourly rate USD','rate',x.rateCents/100,'number','min="0" step="0.01" required')}${check('Barsys team member — no event labor cost','internal',!!x.internal)}${field('Barsys Google email','email',x.email||'','email')}${check('Enable assigned-event crew login','crewAccess',x.crewAccess)}${check('Available for new assignments','active',x.active)}<button>Save staff member</button></form>`).join('')}</div>`;}
function activityView(id){return `<div>${[...state().audit].reverse().filter(x=>!id||x.eventId===id).slice(0,100).map(x=>`<p><strong>${esc(x.action)}</strong> · ${esc(x.actor)} · ${esc(date(x.at))}${x.eventId?' · '+esc(eventName(x.eventId)):''}</p>`).join('')||'<p>No operations recorded yet.</p>'}<p class="muted">Most recent 100 actions shown. Full records remain in the database.</p></div>`;}
$('#content').addEventListener('focusin',e=>{const form=e.target.closest('form');if(form&&dirtyForm&&form!==dirtyForm){notify('Save the current form before editing another section.');dirtyForm.querySelector('input:not([type=hidden]),textarea,select')?.focus();}});
$('#content').addEventListener('input',e=>{if(e.target.id==='event-search'||e.target.id==='event-filter'){filterEvents();return;}if(e.target.id==='inventory-search'){$('#inventory-options').innerHTML=pickerOptions(e.target.value);return;}if(e.target.id==='pack-number'){const q=Number(e.target.value),size=Number(e.target.dataset.size);$('#inventory-form [name=quantity]').value=e.target.value===''?'':Math.round(q*size*1000)/1000;}const form=e.target.closest('form');if(form&&dirtyForm&&form!==dirtyForm){if(e.target.type==='checkbox')e.target.checked=e.target.defaultChecked;else if(e.target.tagName==='SELECT')e.target.value=Array.from(e.target.options).find(x=>x.defaultSelected)?.value||e.target.options[0]?.value;else e.target.value=e.target.defaultValue;notify('Save your current form before editing another section.');return;}if(form?.matches('.stock-form')&&e.target.name==='quantity')form.elements.stockValue.value='';if(form?.id==='flow-prep'){const name=e.target.name;if(name.startsWith('ingredients-'))form.elements['confirmed-'+name.slice(12)].checked=false;if(name.startsWith('equipment-'))form.elements['packed-'+name.slice(10)].checked=false;}if(form){dirtyForm=form;$('#discard').hidden=false;notify('Unsaved edits. Save this form before moving to another section.');}});
// Required-field failures inside collapsed sections were invisible; open the section and say which field blocked the save.
$('#content').addEventListener('invalid',e=>{const el=e.target;let d=el.closest('details');while(d){d.open=true;d=d.parentElement?.closest('details');}const label=el.closest('label')?.firstChild?.textContent?.trim()||el.name||'a required field';notify(`Not saved: complete “${label}” first. ${el.validationMessage}`);},true);
