 if(b.hasAttribute('data-count-adjust')){const form=b.closest('form');if(dirtyForm&&dirtyForm!==form)return;const input=form.elements.quantity;if(input.value===''){notify('Count this item first; unknown stock cannot be incremented.');return;}const item=state().inventory.find(x=>x.id===form.dataset.id),v=Math.round((Number(input.value)+Number(b.dataset.countAdjust))*1000)/1000;if(v<0||(item.kind==='equipment'&&v>1)){notify('Count outside the allowed range.');return;}input.value=v;input.dispatchEvent(new Event('input',{bubbles:true}));}
 if(b.hasAttribute('data-inventory-count')){const form=$('#inventory-form');if(dirtyForm&&dirtyForm!==form)return;form.elements.quantity.value=b.dataset.inventoryCount;const pack=$('#pack-number');if(pack)pack.value='';form.elements.quantity.dispatchEvent(new Event('input',{bubbles:true}));}
 if(b.dataset.openEvent){if(!clean())return;selected=b.dataset.openEvent;showAllDetails=false;viewStep=null;viewSection=0;prep=await api('/api/admin/inquiries/'+selected+'/preparation');history.replaceState(null,'','?event='+selected);render();}
